"""Review raw radix conversion shared body and its two actual far callers."""
import argparse,hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'analysis/tools/python'))
from capstone import Cs,CS_ARCH_X86,CS_MODE_16
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();assert not out.exists() and out.is_relative_to(ROOT/'docs/recovery/evidence');image=(ROOT/'analysis/derived/td2ega-v1/TD2EGA.image.bin').read_bytes();sha=hashlib.sha256(image).hexdigest();assert sha=='8db38a02cc318a62b15928e217bb9f935699c6566088c21d32382a1c908a59c4';graph='analysis/flow/indirect-v8/direct-flow.json';g=json.loads((ROOT/graph).read_text());md=Cs(CS_ARCH_X86,CS_MODE_16)
 def view(ip):
  i=next(md.disasm(image[0x13a80+ip:0x13a80+ip+15],ip,count=1));return {'site':f'13A8:{ip:04X}','bytes':i.bytes.hex(),'text':i.mnemonic+' '+i.op_str}
 selected=[f for f in g['functions'] if f['entry'] in ['13A8:29D0','13A8:29EC']];ips=sorted({ip for f in selected for ip in f['instructions']});observations=[view(ip) for ip in ips]
 expected={0x29d5:'b301',0x29dd:'33d2',0x29e4:'99',0x29f1:'b300',0x2bb0:'8b4e0c',0x2bbc:'57',0x2bbd:'1e',0x2bbe:'07',0x2bbf:'fc',0x2bd0:'aa',0x2be1:'f7f1',0x2be4:'f7f1',0x2bf8:'8805',0x2bfa:'4f',0x2bfb:'ac',0x2bfc:'8605',0x2c08:'58',0x2c0e:'cb',0x0a18:'83c406',0x1cc7:'83c408'}
 for ip,raw in expected.items():assert image[0x13a80+ip:0x13a80+ip+len(raw)//2].hex()==raw,hex(ip)
 callers=[{'owner':f['entry'],**c} for f in g['functions'] for c in f['calls'] if c['target'] in ['13A8:29D0','13A8:29EC']];assert len(callers)==2;windows=[]
 for c in callers:
  f=next(f for f in g['functions'] if f['entry']==c['owner']);site=int(c['site'][5:],16);windows.append({'caller':c,'instructions':[view(ip) for ip in sorted(f['instructions']) if site-25<=ip<=site+16]})
 record={'schema':1,'result':'pass','image_sha256':sha,'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'instruction_observations':observations,'direct_caller_candidates':callers,'caller_instruction_windows':windows,'flow_ledger':graph,'flow_ledger_sha256':hashlib.sha256((ROOT/graph).read_bytes()).hexdigest(),'facts':['29D0 takes SS value16/destNear/radix, BL1, decimal-only wordCWD. 29EC takes SS valueLow/valueHigh/destNear/radix, BL0 and never enters decimal sign prefix. Shared XCHG AX/BX preserves source upper bytes and detects BL through AL. No source C prototype inferred.','Actual PUSHDS/POPES and CLD precede optional sign STOSB and shared long-division digit loop. Radix is arbitrary raw word: zero faults, one can repeat forever for nonzero value, above36 digit byte additions wrap. No clamp or replacement text is invented.','LowwordNEG/ADChigh/NEGhigh forms signed decimal magnitude; two unsigned word DIV steps retain source GPR. Successful DIVFLAGS are undefined; later digit arithmetic/OR/CMP establishes CF before admitted prefixes/return. Fault prefixes stop before instruction/exception delivery.','NUL store followed by do-once byte reversal uses wrapped SI/DI and unsigned CMP(LEA SI+1),DI. It is not replaced with a host reverse loop assuming no address wrap. Output can alias real saved words and far frame.','POPAX returns actual saved destination word, POPDI/POPSI/MOVSPBP/POPBP/plain RETF consumes four frame bytes. Actual callers0978:0A13 and1C00:1CC2 execute ADDSP6/8 respectively, redefining arithmetic FLAGS immediately after return.'],'limits':'Static shared-body and two direct caller operand windows only. Source output capacity, actual caller/formatting context, arbitrary value/radix producers, DS/SS/lifetime/writers/exclusion, otherFLAGS/newcaller/core and resource-fedP2/P3/runtime/gameplay/fidelity remain open.'};out.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'result':'pass','sites':len(ips),'callers':len(callers)}))
if __name__=='__main__':main()
